    // Check invalid access flags
    int access = msign.getAccessFlags();
    if (!wd.allowFinalMethods) {
        if ((access & AsmUtil.ACC_FINAL) != 0) {
            // Detect final throw new ProxettaException ("Unable to create proxy for final method: " + msign + ". Remove final modifier or change the pointcut definition.");
        }
