public String decrypt(String str) {
    try {
        // Replace spaces with chars
        str = StringUtil.replaceChar(str, ' ', ' ');

        // Decode Base64 to get bytes
        byte[] dec = Base64.decode(str);

        // Decrypt using cipher
        byte[] utf8 = dcipher.doFinal(dec);

