```java
public static long computePosition(final int activeTermId, final int termOffset, final int positionBitsToShift, final int initialTermId) {
    // Calculate the number of terms between activeTermId and initialTermId
    final long termCount = activeTermId - initialTermId;

    // Shift the result by positionBitsToShift bits to the left
    final long shiftedResult = termCount << positionBitsToShift;

    // Add termOffset to the shifted result
    final long finalPosition = shiftedResult + termOffset;

    return finalPosition;
}
