public E addAndGetEvicted(E e) {
    // Check if the input element is not null
    checkNotNull(e);

    // Check if the delegate's size is equal to the maximum size
    if (maxSize == 0) {
        return null;
    }

    // Remove the oldest element if the delegate's size exceeds the maximum size
    E evicted = null;
    if (size() == maxSize) {
        evicted = delegate.remove();
    }

    // Add the new element to the delegate
    delegate.add(e);

    // Return the oldest element that was removed if the delegate's size exceeded the maximum size
    return evicted;
}
