public T getIdleRunner(long idleTime) {
    // Poll the first runner from the queue
    QueueItem<T> item = queue.poll();

    // If the queue is empty, return null
    if (item == null) {
        return null;
    }

    // If the runner was not idle for the expected time, put it back to the queue
    if ((System.currentTimeMillis() - item.timestamp) < idleTime) {
        queue.add(item);
        return null;
    }

    // Otherwise, return the runner
    return item.runner;
}
