public void write(Batch batch, SchemaTableClassifier schemaTableClassifier, LoadingCache<SchemaAndTable, JdbcRecordWriter> recordWriters, ErrorRecordHandler errorRecordHandler, boolean perRecord) throws StageException {
    // Classify the data into partitions
    Multimap<SchemaAndTable, Record> partitions = schemaTableClassifier.classify(batch);

    // Iterate over each partition
    for (SchemaAndTable key : partitions.keySet()) {
        Iterator<Record> recordIterator = partitions.get(key).iterator();

        // Write the records in the partition
        write(recordIterator, key, recordWriters, errorRecordHandler, perRecord);
    }
}
