public void write(Batch batch, ELEval tableNameEval, ELVars tableNameVars, String tableNameTemplate, LoadingCache<String, JdbcRecordWriter> recordWriters, ErrorRecordHandler errorRecordHandler, boolean perRecord) throws StageException {
