/**
 * Registers a new cluster in the database.
 * 
 * @param cluster The cluster to be registered.
 * @return The ID of the newly registered cluster.
 * @throws OConfigurationException if the cluster is already registered in the database.
 */
private int registerCluster(final OCluster cluster) {
    if (cluster == null) {
        throw new OConfigurationException("Cannot add cluster '" + cluster.getName() + "' because it is already registered in database '" + name + "'");
