public static String normalizeFieldPathToParamName(String fieldPath) {
    // Check if the input contains a dot
    if (fieldPath.contains(".")) {
        // Split the string into parts
        String[] parts = fieldPath.split("\\.");
        // Initialize a StringBuilder to build the result
        StringBuilder sb = new StringBuilder();
        // Convert the first part to lowercase
        sb.append(lowercase(parts[0]));
        // Iterate through the remaining parts
        for (int i = 1; i < parts.length; i++) {
            // Convert each part to uppercase
            sb.append(uppercase(parts[i]));
        }
        // Return the normalized string
        return sb.toString();
    } else {
        // If no dot is found, convert the entire string to lowercase
        return lowercase(fieldPath);
    }
}
```

