public static int compareVersions(String v1, String v2) {
    // Split the version strings into arrays of components
    String[] components1 = v1.split("\\.");
    String[] components2 = v2.split("\\.");

    // Find the minimum length of the two component arrays
    int length = Math.min(components1.length, components2.length);

    // Compare each component pair
    for (int i = 0; i < length; i++) {
        String s1 = components1[i];
        String s2 = components2[i];

        // Attempt to parse the strings into integers
        Integer i1 = tryParseInteger(s1);
        Integer i2 = tryParseInteger(s2);

        // Compare the integers
