public int readInt() {
    // Check if there are at least four bytes available
    if (available() < 4) {
        throw new RuntimeException("not enough data available, check available() > 4 before calling");
    }

    // Read four bytes from the stream
    int ch1 = poll();
    int ch2 = poll();
    int ch3 = poll();
    int ch4 = poll();

    // Construct the integer by shifting each byte to its correct position
    return (ch4 << 24) + (ch3 << 16) + (ch2 << 8) + (ch1 << 0);
}
