/**
 * Calculates the exponential of a given BigDecimal value using a specified MathContext.
 * 
 * @param mc The MathContext object specifying the precision and rounding mode.
 * @return The result of the exponential calculation.
 */
public static BigDecimal exp(final MathContext mc) {
    // Check if the precision of mc is less than the precision of E
    if (mc.getPrecision() < E.precision()) {
        // Return the result of rounding mc to the same precision as E
        return E.round(mc);
    } else {
        // Create a new BigDecimal object uni with a precision equal to mc
        BigDecimal uni = scalePrec(BigDecimal.ONE, mc.getPrecision());
        // Delegate the calculation of the exponential of uni to a public method named exp
        return exp(uni);
    }
}
