/**
 * Determines the character encoding of a given byte array.
 *
 * @param content The byte array to analyze.
 * @param declaredCharset The declared character encoding, if available.
 * @param maxLengthCharsetDetection The maximum length of the content to analyze for charset detection.
 * @return The detected character encoding as a String, or null if the detection fails.
 */
private static String getCharsetFromText(byte[] content, String declaredCharset, int maxLengthCharsetDetection) {
    CharsetDetector charsetDetector = new CharsetDetector();
    charsetDetector.enableInputFilter(true);
    if (declaredCharset != null) {
        charsetDetector.setDeclaredEncoding(declaredCharset);
    }
    byte[] subContent = content;
    if (maxLengthCharsetDetection != -1 && content.length > maxLengthCharsetDetection) {
        subContent = Arrays.copyOfRange(content, 0, maxLengthCharsetDetection);
    }
    charsetDetector.setText(subContent);
    try {
        CharsetMatch charsetMatch = charsetDetector.detect();
        return validateCharset(charsetMatch.getName());
    } catch (Exception e) {
        return null;
    }
}
