public int findIdx(int want) {
    if (isConstant) {
        return (want == start) ? 0 : -1;
    } else if (isSequential) {
        return want - start;
    } else if (isSorted) {
        return Arrays.binarySearch(raw, want);
    } else {
        for (int i = 0; i < raw.length; i++) {
            if (raw[i] == want) {
                return i;
            }
        }
        return -1;
    }
}
