```java
public Member findMember(String memberName) {
    // Input validation
    if (memberName == null) {
        return null;
    }

    // Initialize the hash table if it's null
    if (memberHash == null) {
        int initial_capacity = (int) (members.size() / 0.75) + 1;
        memberHash = new HashMap<>(initial_capacity);
        for (Member m : members) {
            memberHash.put(m.getName(), m);
        }
    }

    // Return the member associated with the given name
    return memberHash.get(memberName);
}
