/**
 * Removes an IOServiceProvider from the list of registered providers if it matches a given class.
 * 
 * @param iospClass The class of the provider to be removed.
 * @return true if a provider was removed, false otherwise.
 */
static public boolean iospDeRegister(Class iospClass) {
    for (int i = 0; i < registeredProviders.size(); i++) {
        IOServiceProvider spi = registeredProviders.get(i);
