```java
/**
 * Validates the database by checking its header and integrity.
 * If an exception occurs, it closes the database connection before rethrowing the exception.
 * @param sqliteDatabase The SQLiteDatabase object to be validated.
 * @param validateHeader Whether to validate the database header.
 * @param validateIntegrity Whether to validate the database integrity.
 * @param close Whether to close the database connection after validation.
 * @param closeOnError Whether to close the database connection if an exception occurs.
 */
private void validateDatabase(SQLiteDatabase sqliteDatabase, boolean validateHeader, boolean validateIntegrity, boolean close, boolean closeOnError) {
    try {
        if (validateHeader) {
            validateDatabaseHeader(sqliteDatabase);
        }
        if (validateIntegrity) {
            validateDatabaseIntegrity(sqliteDatabase);
        }
    } catch (Exception e) {
        if (closeOnError) {
            sqliteDatabase.close();
        }
        throw e;
    }
    if (close) {
        sqliteDatabase.close();
    }
}
```

