public String pullDump2PC() {
    // Retrieve the serial number of the device
    String serial = device.getSerialNumber();

    // Create a file in the temporary directory of the local machine with the name serial.xml
    File dest = new File(FileUtils.getTempDirectory(), serial + ".xml");

    // Set the path to the destination file
    String path = dest.getPath();

    // Log debug information
    log.debug("pull dump file to pc's path {}", path);

    // Execute the 'pull' command from ADB to copy the dump file
    CommandLine commandPull = adbCommand("pull", "/data/local/tmp/local/tmp/qian.xml", path);

    // Capture the output of the 'pull' command
    String out = executeCommandQuietly(commandPull);

    // Log the output of the 'pull' command
    log.debug("pull dump file to pc's result {}", out);

    // Return the path to the destination file
    return path;
}
