@Override
public ScanResult<String> scan(String cursor, ScanParams params) {
    // Extract the MATCH argument from the scan params
    Collection<byte[]> rawParams = params.getParams();
    boolean isKey = true;
    String match = null;
    boolean foundMatchKey = false;

    // Iterate over the list of raw parameters
    for (byte[] raw : rawParams) {
        if (isKey) {
            String key = new String(raw);
            if (key.equals(new String(MATCH.raw))) {
                // Found the MATCH key, set the match variable and break the loop
                foundMatchKey = true;
                match = new String(raw);
                break;
            }
        } else {
            // If we've found the MATCH key, no need to continue searching
            if (foundMatchKey) {
                break;
            }
        }
        // Toggle the key search mode
        isKey = !isKey;
    }

    // Return a ScanResult with the cursor and the list of keys found
    return new ScanResult<>("0", new ArrayList<>(keys(match)));
}
