/**
 * Retrieves the IP address for a given host name from a properties file.
 * 
 * @param host The host name for which to retrieve the IP address.
 * @return The IP address for the specified host name, or the original host name if not found.
 */
static synchronized String lookupNetworkHost(String host) {
    try {
        if (_bundle == null) {
            URL url = GemFireJmxClient.class.getResource(hostPropFileName);
            String filePath = (url == null) ? hostPropFileName : url.toString();
            System.out.println(new StringBuilder("Loading IP addresses from ").append(filePath).toString());
            _bundle = ResourceBundle.getBundle("host");
        }
        System.out.println(new StringBuilder("Looking for host name \"").append(host).append("\" IP address in ").append(hostPropFileName).toString());
        String newHost = _bundle.getString(host);
        System.out.println(new StringBuilder(host).append("=").append(newHost).toString());
        return newHost;
    } catch (RuntimeException e) {
        System.out.println("Using host:" + host);
        return host;
    }
}
