private static char[] _toCharBitArray(long pvalue, int size)
{
    long value = pvalue;
    char[] bits = new char[size]; // Convert each bit from right to left.
    for (int i = size - 1; i >= 0; --i)
    {
        bits[i] = (value & 1) == 0 ? ' ' : ' '; // Set the bit to ' ' if it's 0, otherwise ' '
