```java
public static String normalize(String publicId) {
    // Replace multiple spaces with a single space
    String normal = publicId.replace(' ', ' ');

    // Replace multiple spaces with a single space again
    normal = normal.replace(' ', ' ');

    // Replace multiple spaces with a single space one last time
    normal = normal.replace(' ', ' ');

    // Trim leading and trailing spaces
    normal = normal.trim();

    // Remove double spaces
    int pos;
    while ((pos = normal.indexOf("  ")) >= 0) {
        normal = normal.substring(0, pos) + normal.substring(pos + 1);
    }

    return normal;
}
```

