public boolean push(Object obj) {
    // Check if the array is full
    if (isFull()) {
        return false;
    }

    // Grow the array if necessary
    if (size == objects.length) {
        grow();
    }

    // Add the object to the array
    objects[size++] = obj;

    // Return true
    return true;
}
