        return false;
    }

    // Initialize an index to traverse the requestPath
    int i = 1;

    // Iterate through the requestPath
    for (int j = 0; i < requestPath.length(); ++i, ++j) {
        // If a space is encountered in the requestPath, check if the remaining characters match the pathComponent
        if (requestPath.charAt(i) == ' ') {
            return j == pathComponent.length();
        }

        // If the current character in requestPath is not equal to the corresponding character in pathComponent, return false
        if (j == pathComponent.length()) {
            return false;
        }

        // Convert both characters to lowercase and compare them
        if (Character.toLowerCase(requestPath.charAt(i)) != Character.toLowerCase(pathComponent.charAt(j))) {
            return false;
        }
    }

    // If the loop completes without finding a mismatch, return false
    return false;
}
```

