```java
public Entry<K, V> getEntry(Object key) {
    // Mask the input key
    Object k = maskNull(key);

    // Calculate the hash value of the masked key
    int hash = hash(k);

    // Find the index in the hash table
    int i = indexFor(hash, table.length);

    // Iterate through the entries in the table
    Entry<K, V> e = table[i];
    while (e != null && !(e.hash == hash && validEntry(e) && eq(k, e.key))) {
        e = e.next;
    }

