```java
/**
 * Adds a new entry to the hash table at the specified bucket index.
 * 
 * @param hash The hash value of the key.
 * @param key The key for the entry.
 * @param value The value associated with the key.
 * @param bucketIndex The index in the table where the entry should be added.
 */
void addEntry(int hash, K key, V value, int bucketIndex) {
    // Create a new entry with the provided hash, key, and value
    Entry<K, V> newEntry = new Entry<>(hash, key, value, table[bucketIndex]);

    // Add the new entry to the table at the specified bucket index
    table[bucketIndex] = newEntry;

    // Set the status of the new entry to ADDED if auto_commit is false
    if (!auto_commit) {
        newEntry.setStatus(Entry.ADDED, getCurrentThreadId());
    }

    // Resize the table if the size exceeds the threshold
    if (size >= threshold) {
        resize(2 * table.length);
    }
}
```

