public static Optional<Boolean> isTarget(EventModel eventModel, Identifiable identifiable) {
    // Check if the EventModel provides a resource with the ID SelectorResource.RESOURCE_ID
    if (eventModel.getListResourceContainer().providesResource(Collections.singletonList(SelectorResource.RESOURCE_ID))) {
        // Get the resource from the EventModel
        ResourceModel resource = eventModel.getListResourceContainer().provideResource(SelectorResource.RESOURCE_ID);
        // Convert the resource to a stream
        Stream<ResourceModel> resourceStream = resource.stream();
        // Map each resource to its resource model
        Stream<ResourceModel> mappedResourceStream = resourceStream.map(ResourceModel::getResource);
        // Filter the mapped resources to include only those that are instances of Identification
        Stream<Identification> identificationStream = mappedResourceStream.filter(resource -> resource instanceof Identification);
        // Map each identification to its object
        Stream<Object> objectStream = identificationStream.map(object -> (Identification) object);
        // Check if any of the objects in the object stream match the given Identifiable
        boolean isOwnerMatch = objectStream.anyMatch(identifiable::isOwner);
        // Return an Optional containing the result of the check
        return Optional.of(isOwnerMatch);
    } else {
        // Return an empty Optional if the resource is not found
        return Optional.empty();
    }
}
```

